def overlap_minutes(meetings: list[list[int]], k: int) -> int:
    diff: dict[int, int] = {}
    for start, end in meetings:
        if start < end:
            diff[start] = diff.get(start, 0) + 1
            diff[end] = diff.get(end, 0) - 1

    total = 0
    active = 0
    prev_time = 0

    for time in sorted(diff):
        if active >= k:
            total += time - prev_time
        active += diff[time]
        prev_time = time

    return total
